<div class="recurrence-layout"><section class="panel editor-panel"><div class="panel-head"><div><h3>Nova recorrência</h3><p>O sistema cria os próximos 12 meses de lançamentos pendentes.</p></div></div><?php if(!$accounts): ?><div class="inline-note">Adicione uma conta antes de configurar uma recorrência. <a href="/accounts">Ir para contas</a></div><?php else: ?>
<form method="post" action="/recurrences/save" class="data-form single"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><label>Tipo<select name="type" data-recurring-type><option value="expense">Despesa</option><option value="income">Receita</option></select></label><label>Descrição<input name="description" required maxlength="140"></label><label>Valor<input name="amount" inputmode="decimal" required placeholder="0,00"></label><label>Conta<select name="account_id"><?php foreach($accounts as $account): ?><option value="<?=(int)$account['id']?>"><?=e($account['name'])?></option><?php endforeach; ?></select></label><label>Categoria<select name="category_id"><option value="">Sem categoria</option><?php foreach($categories as $category): ?><option data-type="<?=e($category['type'])?>" value="<?=(int)$category['id']?>"><?=e($category['name'])?></option><?php endforeach; ?></select></label><label>Frequência<select name="frequency"><option value="daily">Diária</option><option value="weekly">Semanal</option><option value="monthly" selected>Mensal</option><option value="yearly">Anual</option><option value="custom">A cada X dias</option></select></label><label>Intervalo<input type="number" name="interval_value" value="1" min="1" max="365" required><small class="field-hint">Aplicado à frequência escolhida; personalizado usa dias.</small></label><label>Data inicial<input type="date" name="start_date" value="<?=date('Y-m-d')?>" required></label><label>Data final (opcional)<input type="date" name="end_date"></label><label>Observações<input name="notes" maxlength="500"></label><button class="button primary">Criar recorrência</button></form><?php endif; ?></section>
<section class="panel statement-panel"><div class="panel-head"><div><h3>Suas regras</h3><p>As ocorrências geradas permanecem no histórico ao cancelar.</p></div></div><div class="table-wrap"><table><thead><tr><th>Tipo</th><th>Descrição</th><th>Frequência</th><th>Próximo lançamento</th><th>Conta</th><th>Status</th><th class="right">Valor</th><th></th></tr></thead><tbody>
<?php foreach($rules as $rule): ?><tr><td><?=$rule['type']==='income'?'Receita':'Despesa'?></td><td><?=e($rule['description'])?></td><td><?=match($rule['frequency']){'daily'=>'Diária','weekly'=>'Semanal','monthly'=>'Mensal','yearly'=>'Anual',default=>'A cada '.e($rule['interval_value']).' dias'}?></td><td><?=e(date('d/m/Y',strtotime($rule['next_due_date'])))?></td><td><?=e($rule['account_name'])?></td><td><span class="status-pill <?=$rule['status']==='active'?'received':'cancelled'?>"><?=$rule['status']==='active'?'Ativa':'Cancelada'?></span></td><td class="right"><?=money((int)$rule['amount'])?></td><td><?php if($rule['status']==='active'): ?><form method="post" action="/recurrences/cancel"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$rule['id']?>"><button class="row-cancel">Cancelar</button></form><?php endif; ?></td></tr><?php endforeach; ?><?php if(!$rules): ?><tr><td colspan="8" class="table-empty">Nenhuma recorrência configurada.</td></tr><?php endif; ?></tbody></table></div></section></div>
